                        inf->state++;
                        inf->n = 0;

                        /* fallthru */
                case UPNS_ID_BL_GB_BTYPE_0d:

                        if (inf->n < inf->len) {

                                r = read_byte(inf, &t);
                                if (r)
                                        return r;

                                inf->out[inf->outpos++] = t;
                                if (inf->outpos >= inf->outlen)
                                        inf->outpos = 0;
                                inf->outpos_linear++;
                                inf->n++;

                                if (inf->outpos_linear - inf->consumed_linear >=
                                                inf->bypl + 1) {
                                        return LWS_SRET_WANT_OUTPUT;
                                }

                                continue;
                        }

                        inf->treepos = 0;
                        inf->state = UPNS_ID_BL_GB_DONE;
                        continue;

